INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lazersilk', 172465, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3vnx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdrwi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lazersilk', 'In Lazer Silk, you play as a spider who rules over an elliptical web. Flower petals, flies, and wasps will intermittently blow in from a central vortex, and deposit themselves in your web. The spider can move across all quadrants of the spider web, and gains points by collecting flies and flower petals. If they are not cleared quick enough, they will leave a hole in the web which can not be traversed. If the spider touches a wasp, they will lose a life. Other spiders will descend vertically through the web, and they must be avoided. Small chewing insects will invade the web, and chew pieces out of your home. There are even enemies that incessantly chase the player.' FROM games WHERE igdb_id = 172465 ON CONFLICT (game_id, language_code) DO NOTHING;
