INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3d-bowling', 281224, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co83vo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs13c.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Bowling', '3D Bowling is a sports game where you are charged with the task of knocking over ten pins at the end of a lane with your bowling ball. When it is your turn, you are shown both a side-view of the lane as well as a view of the pins. The controls allow you to position yourself across the lane, then when ready, to step towards the foul line and release the ball towards your targets. On release, you may choose to hook the ball to the left or right. Stepping across the foul line results in a zero score for that throw. Otherwise, you will see the ball travel up the lane, and then switch to an "expanded view" of the pins as the ball arrives. Pins are reset after each strike, and if there are no pins standing after the second throw, you are awarded a bonus throw, allowing up to 30 points per frame for a total of 10 frames. There are both one and two player game options.' FROM games WHERE igdb_id = 281224 ON CONFLICT (game_id, language_code) DO NOTHING;
