INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('protector-ii', 18571, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/egt31voytsgf1bbkmqse.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqci8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Protector II', 'An arcade style game with a loose basis on the arcade hit Defender, Protector II is a side-scrolling shooter. Like Defender, there are lots of different aliens to contend with, and some ground based enemies as well. There are no smart bombs, however. You have to rescue humans as well (twice) from both an alien ship, and later a city that will be overrun with lava from a volcano that erupts during the game; all the while protecting them from aliens. You then have to drop them one at a time (unlike Defender, you can only carry one human at a time) into a teleporter tube to get them off the planet entirely. The game is quite difficult, with some very precise flying required at times (probably even more difficult than Defender or Stargate). It also has more of a "plot" than the arcade games it is based on, with several sub-missions of rescue depending on what stage you are at (it should be noted that there is no breaks between "stages" - the whole game play is continuous).' FROM games WHERE igdb_id = 18571 ON CONFLICT (game_id, language_code) DO NOTHING;
