INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chess Player', 'The Chess Player provides players with options to save games, print moves, and even change sides during a match. The game also includes features like castling and en-passant captures, adding depth to the chess experience. The integration of these features makes The Chess Player a comprehensive chess simulation for its time.' FROM games WHERE igdb_id = 380106 ON CONFLICT (game_id, language_code) DO NOTHING;
