INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey & Donald', 'Mickey & Donald is a Multi Screen Game & Watch video game released in 1982 by Nintendo. It stars the two Disney properties Mickey Mouse and Donald Duck. The game''s model number is DM-53 (D standing for Donald and M standing for Mickey). In the game, you''ll control both of the characters whose goals are to extinguish fires.' FROM games WHERE igdb_id = 145210 ON CONFLICT (game_id, language_code) DO NOTHING;
