INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil Fish', 'The player controls a dog who must feed squids in order to make them trap themselves on the several passages of the maze, as they will be too fat to advance. When they are trapped, the dog must go against them and touch them. Immediately after that, a little house will appear on the center of the maze. Touch it and a part of a drawing will be revealed. Repeat this procedure until the image is totally revealed and you''ll pass to the next level.' FROM games WHERE igdb_id = 39633 ON CONFLICT (game_id, language_code) DO NOTHING;
