INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('journey-escape', 22415, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mgwgwhlgevsu5k19mupz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6kzu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey Escape', 'You''re on the road with the rock band Journey! After each concert, your goal is to guide the five band members to the escape vehicle so they can get to the next concert on time. You start with $50,000 from the concert and need to guide one band member at a time; the screen scrolls vertically, and you need to get past the crowds and various obstacles before time runs out. Trying to slow you down are numerous fans, reporters, promoters, and photographers. Running into each of these will cause you to lose some of the money you start with, and also precious time! Stage barriers and fences will also cause you to lose time, but you won''t lose any money if you hit one of these. To help you out, roadies and your manager are also in the crowds. They will give you temporary invulnerability allowing you to run straight through any obstacles. The game ends when a band member doesn''t make it to the escape vehicle before the timer runs out. As the game advances, there will be bigger and bigger crowds to avoid, and they will be more aggressive about getting in your way!' FROM games WHERE igdb_id = 22415 ON CONFLICT (game_id, language_code) DO NOTHING;
