INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy''s Demise', 'Spy''s Demise places players in the Soviet Embassy in Pyongyang as they navigate through multiple floors using elevators to collect pieces of an encrypted message. The platforming gameplay revolves around timing elevator movements and avoiding patrolling security guards while ascending the building. Players must gather all message fragments on each floor to progress to the next level.' FROM games WHERE igdb_id = 23315 ON CONFLICT (game_id, language_code) DO NOTHING;
