INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 1.0', 'Even back in 1982, Microsoft''s first release of Flight Simulator was advanced enough to meet FAA regulations, giving players full control of the instrument panel. The sim is loaded with features, configurable for any experience level, and includes more than 20 airports with varied terrain.' FROM games WHERE igdb_id = 3353 ON CONFLICT (game_id, language_code) DO NOTHING;
