INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Maze', 'Lost in a network of mazes - in bad company! Everywhere you turn are mechanical monsters who stole your gold. The monsters are programmed to kill, so keep a cool head and a steady hand. Prepare for a battle as you struggle to keep the gold and find a way out alive!' FROM games WHERE igdb_id = 23302 ON CONFLICT (game_id, language_code) DO NOTHING;
