INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'River Rescue', 'River Rescue is a 1982 game for the Commodore VIC-20, Commodore 64, ZX Spectrum, and Atari 8-bit family. It is one of a number of game titles produced by Thorn EMI Computer Software (later known as Creative Sparks) during 1982 and 1983. A TI-99/4A version was announced but never released.
