INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC-Man', 'A fairly faithful reproduction of the classic Pac-Man arcade game, considering its age and use of CGA graphics. As ever, the main character moves through a maze collecting dots and avoiding ghosts, using power pills for a chance to kill the ghosts for points.' FROM games WHERE igdb_id = 25148 ON CONFLICT (game_id, language_code) DO NOTHING;
