INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Mission Pinball', 'Night Mission Pinball is a pinball game simulation. You can change many physical parameters of the machine to suit your playing style or your whim such as the number of balls, ball speed, the incline of the machine, the kick off the bumpers, etc. It supports 1-4 players and is controlled by the keyboard or joystick.' FROM games WHERE igdb_id = 25138 ON CONFLICT (game_id, language_code) DO NOTHING;
