INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1K ZX Chess', 'Chess game developed for home computer Sinclair ZX81. Game code takes up only 672 bytes in memory, but implements all chess rules except for castling, promotion, and en passant, including a computer opponent. It was the smallest implementation of chess on any computer at the time.' FROM games WHERE igdb_id = 391019 ON CONFLICT (game_id, language_code) DO NOTHING;
