INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Duel', 'Space Duel is an arcade game released in 1982 by Atari Inc. It is a direct descendant of the original Asteroids, with asteroids replaced by colorful geometric shapes like cubes, diamonds, and spinning pinwheels. The player has five buttons: two to rotate the ship left or right, one to shoot, one to activate the thruster, and one for force field. Shooting all objects on the screen completes a level.' FROM games WHERE igdb_id = 18405 ON CONFLICT (game_id, language_code) DO NOTHING;
