INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oil Panic', 'Oil Panic is a video game unit that was released as part of the Game & Watch multi screen series. In the game, the player has to catch dripping oil from an oil leak in a pipe. Once he does, he has to go into his bosses room on the second screen to empty it. If he misses a drop then the player loses a life.' FROM games WHERE igdb_id = 145208 ON CONFLICT (game_id, language_code) DO NOTHING;
