INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Chase', 'Astro Chase is a multidirectional shooter written by Fernando Herrera for Atari 8-bit computers. It was published by First Star Software in 1982 as the company''s first game. Parker Brothers licensed it, releasing cartridge versions for the Atari 8-bit family and Atari 5200 console in 1983 and a Commodore 64 version in 1984. Exidy licensed it for arcade use with its Max-A-Flex cabinet.' FROM games WHERE igdb_id = 12304 ON CONFLICT (game_id, language_code) DO NOTHING;
