INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snipes', 25147, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/b4bfceznv6lll0dtyrxr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pw7jc1qpewheljyq56bs.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snipes', 'Snipes is an arcade style action game. You are in a large maze along with a number of generators. The generators create the enemy Snipes, and to win the game you need to shoot all of the generators and all of the Snipes they create. The game is played using two sets of four keys, one set to move and one to fire; this allows you to both move and fire in eight different directions, and you aren''t limited to firing in the same direction you are facing (similar to the controls in games such as Robotron: 2084). The Snipes are armed as well, and will be firing back at you! If you lose all of your lives, the game ends and the Snipes win. There are numerous skill levels available; in the higher levels the snipes are more numerous, more aggressive, and the maze walls become deadly to touch.' FROM games WHERE igdb_id = 25147 ON CONFLICT (game_id, language_code) DO NOTHING;
