INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tic-Tac-Toe', 'Tic Tac Toe is a BASIC implementation of the familiar strategy game, where each player attempts to form a line of either noughts or crosses through the 3x3 game board. Two human players may challenge each other, or one may test his wits against the computer (the human player always goes first). When playing against the machine, its degree of cunning depends on the chosen skill levels: "basic", "more difficult" or "most difficult".' FROM games WHERE igdb_id = 88434 ON CONFLICT (game_id, language_code) DO NOTHING;
