INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cathouse-blues', 40629, '1982-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yk2.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cathouse Blues', 'In Cathouse Blues, you are a horny guy who has to memorize which 7 houses the ladies of ill repute wander into. Grab some cash from the teller, and visit each woman. A visit will cost $20, at which time you''ll find yourself in her bed. Score with her as many times as you can before you''re forced to leave for the next. The cops are in pursuit as well as a mugger who wants your money. Visiting a wrong house will cause you to be temporarily immobilized (a sitting duck for the cops) as you figure out what to do next. The roles of the men and women are switched in Gigolo.' FROM games WHERE igdb_id = 40629 ON CONFLICT (game_id, language_code) DO NOTHING;
