INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RealSports Football', 'RealSports Football is a 1982 football video game made by Atari for the Atari 2600, Atari 5200 and Atari 8-bit computer platforms. RealSports Football presents a greatly simplified version of football for play. Players in the game cannot go out of bounds or fumble the football, and there are no penalties in the game. Also, touchdowns automatically score 7 points; there is no kicking for extra points.' FROM games WHERE igdb_id = 18418 ON CONFLICT (game_id, language_code) DO NOTHING;
