INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cotocoto Cottong', 'Players manipulate a four-way joystick and a Speed button to control the direction and acceleration of their train as it rumbles down the track to the tune of "I''ve Been Working On The Railroad". The basic idea is to keep from running off the track. To get really big scores, though, players must drive locomotives into the passenger stations and pick up the waiting strap-hangers. There is even a bonus station that can only be reached during a limited time period. The faster the player gets to the special station, the more bonus points he or she collects (from 1000 to 5000).' FROM games WHERE igdb_id = 38621 ON CONFLICT (game_id, language_code) DO NOTHING;
