INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteroids', 'Asteroids (Silversoft) is a clone of the Arcade version which sees your craft in the middle of an asteroid field and you must destroy all the asteroids to survive. The asteroids start off large and when you shoot one then it splits into two, and shooting an asteroid this size splits it into two again before being destroyed with another shot. Occasionally an alien craft appears moving across the screen and this can be destroyed for extra points. If you are hit by an asteroid or the alien craft then you lose one of three lives. You are able to turn your ship 360 degrees as well as move forward.' FROM games WHERE igdb_id = 319567 ON CONFLICT (game_id, language_code) DO NOTHING;
