INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teeter Torture', 'Teeter Torture is a game that has rather mysterious origins. Only a single cabinet has even been found for it. (Fortunately it has been making regular appearances at the California Extreme show for a number of years.) For years there was even confusion as to whether it was an Exidy-produced prototype or some bootleg running on the Exidy hardware.' FROM games WHERE igdb_id = 39513 ON CONFLICT (game_id, language_code) DO NOTHING;
