INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Canyon', 'Space Cavern is a 1982 shooter video game for the Atari 2600 developed and released by Games by Apollo. Players control a spaceship commander who has landed on a planet and must defend the ship against its hostile creatures. Games by Apollo founder Pat Roper was impressed by the game Demon Attack and tasked Apollo member Dan Oliver with making a game very similar to it. The game was later rereleased as Space Canyon.' FROM games WHERE igdb_id = 40771 ON CONFLICT (game_id, language_code) DO NOTHING;
