INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('final-approach--1', 95485, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7mpu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqb8i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Approach', 'You are an air traffic controller at an international airport. You must guide planes in to landing safely. Your first screen is the Approach Control Radar screen or ARC. You must guide the aircraft , using the cursor, until they are headed left to right along the yellow line headed towards the black stripe. Make sure the other planes are headed where they won''t immediately head towards each other or off screen. After the plane gets near the black stripe, move the cursor to the center red light and press the button. You will then be on the Ground Control Approach screen or GCA. Here you must center the plane''s nose on the glide slope and localizer before it arrives at the end of the runway. If the landing is successful, the plane will disappear from the ARC screen and a new one will appear soon to take its place. If not, when you press your joystick button and return to the ARC screen, the plane will still be there. If a plane starts flashing on the ARC and you hear an emergency sound, this plane has an emergency and must be landed first. Scoring Successful landing=25 points Successful emergency landing if landing before other planes=50 points Aircraft wanders off radar=lose 5 points You get a control error (lose a life) if you allow a near miss or do not immediately land an aircraft in distress. You are allowed an additional control error (extra life) every 500 points. Game variations Games 1, 3, 5, and 7 are one player. Games 2, 4, 6, and 8 are two player. Maximum number of planes on radar: Games 1, 2, 3, and 4=4 Games 5 and 6=3 Games 7 and 8=2 There are crosswinds on landings in games 3 and 4 only. Difficulty switch A=faster planes B=slower planes' FROM games WHERE igdb_id = 95485 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 95485 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
