INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Springer', 'You control Springer, a pink rabbit that hops from different cloud levels and a few moving clouds picking up bonus object such as carrots, apples, sunglasses and a toothbrush. Kick the evil dino eggs that will hatch into green dinos all under the watchful eye of a big red sun. Your ultimate objective is to reach the sun at the top of the screen with bonus time remaining and maximum bonus points.' FROM games WHERE igdb_id = 18652 ON CONFLICT (game_id, language_code) DO NOTHING;
