INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Arkade', 'As the name suggests, this game brings to the personal computer one of the earliest concepts to appear on arcade and dedicated console game screens: a tank duel. Players look down on a battlefield of two-dimensional obstacles and maneuver their tanks to shoot and destroy each other. Each tank has nine points of armor, allowing eight hits before the final shot destroys the tank and hands victory to the opposing player.' FROM games WHERE igdb_id = 24849 ON CONFLICT (game_id, language_code) DO NOTHING;
