INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eli''s Ladder', 'Eli''s Ladder is an educational game aimed at children, where math problems need to be solved to help Eli and his crew climb a ladder to his space ship so they can then journey to the Moon. The game included a wall chart and stickers designed to help motivate children progress through the problems. This is one of the rarest Atari 2600 games and apparently saw fairly limited distribution.' FROM games WHERE igdb_id = 40642 ON CONFLICT (game_id, language_code) DO NOTHING;
