INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ponpoko', 'You control a tanuki, or raccoon dog, who climbs up ladders, walks across floors and jumps over gaps while avoiding red and yellow snakes. The cat must collect all the fruits and vegetables in order to advance to the next level. There are also baskets that contain either snakes, fruits, vegetables or other bonus items.' FROM games WHERE igdb_id = 39395 ON CONFLICT (game_id, language_code) DO NOTHING;
