INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape', 'Find your way through the endless maze - but do it right or you''re doomed! You are trapped on the top floor of a building. The only way down is in the elevator. Well, that''s easy to find but unless you have the right key it plummets to the ground. The rooms hold the clues but they''re in endless corridors. Will you get out alive?' FROM games WHERE igdb_id = 114755 ON CONFLICT (game_id, language_code) DO NOTHING;
