INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro-Dodge', 'In this Asteroids clone, you get points by shooting enemy ships, and asteroids which gradually break down into smaller and smaller pieces. Your controls are rotating clockwise or counter-clockwise, thrusting, firing, and hyperspace. As you progress, the levels will get more and more difficult as you move into areas with more and more asteroids.' FROM games WHERE igdb_id = 25156 ON CONFLICT (game_id, language_code) DO NOTHING;
