INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fireflies', 'The player controls a bug jar, and attempts to catch all the fireflies which flit about the screen. Fireflies are represented by single pixel dots which intermittently turn on and off as they move randomly about the screen. The player must attempt to guess their location, and correctly open their bug jar while over the firefly.' FROM games WHERE igdb_id = 125850 ON CONFLICT (game_id, language_code) DO NOTHING;
