INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Royal Dealer', 'Pull up a chair and join the party! Your computer-controlled opponents are ready to take you on, in four card game classics -- Crazy Eights, Rummy, Gin Rummy and Hearts. Computer shuffles the deck and deals. Your choice of 1, 2 or 3 poker-faced ladies play the opposing hands. You provide the peanuts and chatter. The computer provides the challenge.' FROM games WHERE igdb_id = 41428 ON CONFLICT (game_id, language_code) DO NOTHING;
