INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snoopy Tennis', 'Snoopy Tennis is a Game & Watch video game released in 1982 by Nintendo. The game was very successful, perhaps due to the Snoopy label, with Nintendo producing an estimated 1,200,000 worldwide. In the game, you control Snoopy, moving him up and down to make him hit the oncoming tennis balls with your racket. It was released on the Wide Screen format. A version of the game was released as a keychain title under the mini-classics label.' FROM games WHERE igdb_id = 145169 ON CONFLICT (game_id, language_code) DO NOTHING;
