INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ali Baba and 40 Thieves', 'Ali Baba and 40 Thieves is a maze arcade game released by Sega in 1982. Players take the role of the famous Arabian hero who must fend off and kill the forty thieves who are trying to steal his money. The game is based on the folk tale of the same name. It was ported to the MSX platform, and then a Vector-06c port was made based on the MSX version.' FROM games WHERE igdb_id = 39468 ON CONFLICT (game_id, language_code) DO NOTHING;
