INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tron', 'Up to two players control light cycles that leave a solid light trail in their wake. The object of the game is to trap the other player by surrounding them with a light trail that they can''t avoid crashing into – or forcing them to run into their own trail. Coming into contact with a light trail, either yours or the other player''s, collapses your own trail and ends your turn. The player still standing at the end of the round wins.' FROM games WHERE igdb_id = 128730 ON CONFLICT (game_id, language_code) DO NOTHING;
