INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beezer', 'Players trap dangerous killer bees. The precise trackball control is used to maneuver through the honeycomb pushing gates to create six sided traps. The bees are lured into the trap and shut in. Eating bee eggs before they hatch gives Beezer super powers to eat bees. However, there are dangers of getting stung or trapped. A winning play strategy keeps players coming back to Beezer.' FROM games WHERE igdb_id = 23569 ON CONFLICT (game_id, language_code) DO NOTHING;
