INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flyboy', 'ake off on a fantastic video trip. A voyage that simulates the thrills and skills of actual Hang Gliding. Players use the joystick to control Freddie, but good timing and strategy is necessary to successfully negotiate invisible air currents, wind direction and up and down drafts. This game has incredible visual impact for this time, Freddie flies the skies over the Alps--over trains, trees, bridges, through winter and summer seasons; over the Pacific--over a yacht, tropical islands, an aircraft carrier; and over Egypt--camels, Pyramids, the Taj Mahal, the Sphinx, through day and night landscapes. It''s a complete global challenge with non-stop action over a continuously changing panorama below.' FROM games WHERE igdb_id = 39894 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 39894 AND p.igdb_id = 52 ON CONFLICT DO NOTHING;
