INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zzyzzyxx', 175634, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3yrr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqgap.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zzyzzyxx', 'The object of the game is to guide the protagonist, named Zzyzzyxx, through a moving maze of bricks to collect gifts and bring them to the fair-haired Lola, the object of his affection. Zzyzzyxx is opposed by the evil trio by the names Boris, Bluto and Smoot, also known as the Rattifers. These three will try to intercept Zzyzzyxx as he makes his way through the maze. He can collect a helmet in the maze, which can be used to imprison a Rattifer inside a brick, or to break a brick in the row above to move through the maze. As the levels progress, Zzyzzyxx must avoid crumbling bricks, rising missiles, and dropping bombs. The game has a 1up player score and laps tallied at the top of the screen.' FROM games WHERE igdb_id = 175634 ON CONFLICT (game_id, language_code) DO NOTHING;
