INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Congo', 'Congo is an action game where the player is in control of a raft that is floating down the Congo river. Taking place after a ship wreck, the player''s task is to rescue his ship mates who are stranded along the shore as well as on islands in the river. One survivor can be picked up at a time and has to be dropped off at a safe harbour before time runs out.' FROM games WHERE igdb_id = 172468 ON CONFLICT (game_id, language_code) DO NOTHING;
