INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4 in 1 Row', 'Connect 4 ring any bells, it should do, this game is a variation on the paper/pen classic 0X0 also, all you have to do to beat your opponent is simply out manoeuvre them in a strategy game of getting 4 of your colours in one row while blocking your opponent from doing the same.' FROM games WHERE igdb_id = 41534 ON CONFLICT (game_id, language_code) DO NOTHING;
