INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abductor', 'Abductor is a side view single screen shooter where you control a spacecraft at the bottom of the screen, moving left or right, and you have to blast and destroy all aliens that appear in various formations above. Below your craft are six humans and you must stop them being taken by swooping aliens to the top of the screen and if they reach the top, they turn into skulls and fall down the screen. If you are hit by an alien or falling skull then you lose one of three lives but if you lose all the humans then it is game over.' FROM games WHERE igdb_id = 41192 ON CONFLICT (game_id, language_code) DO NOTHING;
