INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('verkehrsspiele-1', 283016, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7n7g.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Verkehrsspiele 1', 'The CSV Video-Traffic Games Edition of the G7000 was given to primary schools in a small region of West Germany. The package consisted of a G7000 and two special games -- Verkehrsspiele 1 and Verkehrsspiele 2 -- that were used to teach children how to behave on the street. The console set is nothing more than a repackaging of a regular Philips G7000. The package comes with a special "Video-Traffic Games" sticker affixed to the TV screen depicted by the box art. It contains a regular G7000, the two games, and some documentation. The first volume of the traffic games was also given away to members of the German Commander-ROM club as Videopac "V," and retitled Kinder im Verkehr 1 (Kids in Traffic 1). The manual claims that Videopac V was the first of a series of new learning games aimed at kids 6 to 14 years old. From this, one might surmise that "Kinder im Verkehr 2" was planned for release, but no copies have been found. In all forms, the traffic games are quite rare, with Videopac V being a bit less difficult to find than the Verkehrsspiele games.' FROM games WHERE igdb_id = 283016 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 283016 AND p.igdb_id = 133 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bolo', 21916, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8g7z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqatz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bolo', 'Upon startup Bolo requests a level number (1–9) and density (1–5); the game then generates a random rectangular maze containing six enemy bases. The higher the density specified, the more walls appear in the maze. The player controls a tank, and must destroy the six enemy bases to advance to the next level. The player can view 1/132 of the maze at one time; indicators on the right side of the screen show the player''s position within the maze, the direction of the enemy bases and the fuel remaining.
