INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball', 'Pinball recreates a pinball table where the aim is to keep hitting a ball to score as many points as you can with two flippers. The table is equipped with bumpers and letters spelling TIMEX, as well as two lanes that when entered give bonus points. There are also two outside lanes that when entered lose the ball and if the ball also passes the flippers then you lose one of five lives.' FROM games WHERE igdb_id = 319529 ON CONFLICT (game_id, language_code) DO NOTHING;
