INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turmoil', 'The player controls a space ship which is trapped in an area consisting of seven tunnels which are connected by a vertical shaft. Enemies are attacking the player from left and right and it is the objective of the player to destroy as many attackers as possible using the shaft. You can''t, however, hover at one spot for too long since an invincible enemy will appear, forcing the player to change positions eventually.' FROM games WHERE igdb_id = 18559 ON CONFLICT (game_id, language_code) DO NOTHING;
