INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('capture--2', 281217, '1982-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co84rh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs2v4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capture', 'Capture is a strategy game clone of Reversi or Othello, Capture has players taking turns placing black and red game pieces on a green 64-space grid. The objective is to trap the other player''s pieces and several pieces can be trapped at once. When a piece gets trapped, it changes to the colour of the trapping player''s pieces. When the board gets full, the player occupying the most spaces wins the game. Games can be timed, and players can give or take a time handicap. There are six different skill levels from which to choose.' FROM games WHERE igdb_id = 281217 ON CONFLICT (game_id, language_code) DO NOTHING;
